/**
 * Illustrations for exercises. The pictures are generated by
 * `tools/exercise-illustrations` (pnpm exercises:build) into public/exercises.
 * A plan stores only the exercise name, so a name is matched to the movements
 * it mentions. Names that match nothing fall back to a Google Images search.
 */

export interface Movement {
  id: string;
  label: string;
}

interface Rule {
  id: string;
  /** Any of these (after normalisation) must appear in the name. */
  any?: string[];
  /** All of these must appear. */
  all?: string[];
  /** None of these may appear. */
  not?: string[];
  /** Whole normalised name must match (for names that are only numbers). */
  pattern?: RegExp;
}

