/** Block and phase labels that are not searchable exercises. */
const structural =
  /^(blocco|avvio|sviluppo|chiusura|parte|circuito|riscaldamento|defaticamento|progressivo|salite|piramide|vo2max|sweet spot|prova ftp|z2|extra facoltativo)\b/;

export const isStructuralLabel = (name: string) =>
  structural.test(normalizeExerciseName(name));

/** Lowercase, no accents, punctuation turned into single spaces. */
export function normalizeExerciseName(name: string): string {
  return name
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

/** Movement ids mentioned by an exercise name, in the order they appear. */
export function movementsForName(name: string): string[] {
  const text = ` ${normalizeExerciseName(name)} `;
  const has = (term: string) =>
    text.includes(` ${term}`) || text.includes(term);
  const found: { id: string; at: number }[] = [];
  for (const rule of rules) {
    if (rule.pattern) {
      if (rule.pattern.test(normalizeExerciseName(name)))
        found.push({ id: rule.id, at: 0 });
      continue;
    }
    if (rule.all && !rule.all.every(has)) continue;
    if (rule.any && !rule.any.some(has)) continue;
    if (rule.not?.some(has)) continue;
    const terms = [...(rule.all ?? []), ...(rule.any ?? [])];
    const at = Math.min(
      ...terms.map((t) => text.indexOf(t)).filter((i) => i >= 0),
    );
    found.push({ id: rule.id, at });
  }
  // A name that mentions a specific variant should not also show its base.
  const ids = new Set(found.map((f) => f.id));
  if (ids.has("side-plank")) ids.delete("plank");
  return found
    .filter((f) => ids.has(f.id))
    .sort((a, b) => a.at - b.at)
    .map((f) => f.id);
}

export const movementImage = (id: string) => `/exercises/${id}.svg`;
export const movementAnimation = (id: string) => `/exercises/anim/${id}.svg`;
export const movementThumb = (id: string) => `/exercises/thumbs/${id}.svg`;

export const movementLabel = (id: string) =>
  movements.find((m) => m.id === id)?.label ?? id;

/** Name without technique notes, for search links ("Leg curl – Myo-reps"). */
export function searchTerm(name: string): string {
  return name
    .replace(/^[A-Z]\d\s*[·.:-]\s*/, "")
    .replace(/\([^)]*\)/g, " ")
    .split(/\s[–-]\s/)[0]!
    .replace(/\s+/g, " ")
    .trim();
}

export const googleImagesUrl = (name: string) =>
  `https://www.google.com/search?tbm=isch&q=${encodeURIComponent(`${searchTerm(name)} esercizio`)}`;

export const youtubeSearchUrl = (name: string) =>
  `https://www.youtube.com/results?search_query=${encodeURIComponent(`${searchTerm(name)} tecnica`)}`;
